<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Invoice {{ $order->order_number }} | {{ $brandName }}</title>
<style>body{margin:0;background:#eef3f7;color:#172b3a;font:14px Arial,sans-serif}.invoice{width:min(850px,calc(100% - 30px));margin:35px auto;padding:45px;background:#fff;box-shadow:0 8px 30px rgba(0,0,0,.08)}header{display:flex;justify-content:space-between;border-bottom:3px solid #0b3d62;padding-bottom:22px}.brand-logo{max-width:180px;max-height:65px}h1,h2{color:#0b3d62;margin:0 0 10px}.meta{text-align:right}.details{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin:30px 0}.details p{margin:4px 0}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #dce5ed;text-align:left}th{background:#f4f7fa;color:#0b3d62}.number{text-align:right}.totals{width:340px;margin:25px 0 0 auto}.totals div{display:flex;justify-content:space-between;padding:7px}.totals .grand{font-size:20px;font-weight:bold;border-top:2px solid #0b3d62}.actions{text-align:center;margin:25px}.actions button{padding:11px 20px;border:0;background:#f5821f;color:#fff;font-weight:bold;cursor:pointer}@media print{body{background:#fff}.invoice{width:auto;margin:0;padding:20px;box-shadow:none}.actions{display:none}}@media(max-width:600px){.invoice{padding:22px}.details{grid-template-columns:1fr}.totals{width:100%}}</style></head>
